mapper.select:
SELECT COUNT(*)
FROM medical_registration mr
    LEFT JOIN patient_user_info pi ON mr.patient_card_id = pi.id
    LEFT JOIN doctor d ON mr.doctor_id = d.id
    LEFT JOIN medical_dept_sub mds ON mr.dept_sub_id = mds.id
    LEFT JOIN medical_dept md ON mds.dept_id = md.id
WHERE 1 = 1

    AND pi.name LIKE CONCAT('%',#{name},'%')


    AND pi.sex = #{sex}


    AND md.id = #{deptId}


    AND mds.id = #{deptSubId}


    AND d.id = #{doctorId}


    AND mr.status = #{status}

SELECT pi.id AS patientCardId, pi.name AS name, pi.sex AS sex, pi.pid AS pid, pi.tel AS tel, md.name AS deptName, mds.name AS deptSubName, d.name AS doctorName, mr.date AS date, mr.slot AS slot, mr.status AS status, mr.id AS registrationId, mr.payment_status AS paymentStatus FROM medical_registration mr LEFT JOIN patient_user_info pi ON mr.patient_card_id = pi.id LEFT JOIN doctor d ON mr.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mr.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE 1 = 1
AND pi.name LIKE CONCAT('%',#{name},'%')
AND pi.sex = #{sex}
AND md.id = #{deptId}
AND mds.id = #{deptSubId}
AND d.id = #{doctorId}
AND mr.status = #{status}
ORDER BY mr.create_time DESC LIMIT #{start}, #{length}
